        self.messages = []
        self.translations = []  # for translation tool history

    def add_message(self, sender_id, text, translated_text=None):
        self.messages.append({
            "sender_id": sender_id,
            "text": text,
            "translated_text": translated_text
        })
        if translated_text:
            self.translations.append({
                "original": text,
                "translation": translated_text,
                "from_lang": self.language1 if sender_id == self.user1_id else self.language2,
                "to_lang": self.language2 if sender_id == self.user1_id else self.language1
            })

