        self.status = "completed"


class LanguageExchangeService:
    def __init__(self, user_registry):
        self.user_registry = user_registry
        self.sessions = {}  # session_id -> LanguageExchangeSession
        self.pending_matches = []  # list of (user_id, languages) waiting for match

    def request_exchange(self, user_id, native_language, learning_language):
        # Try to find a match
        for i, (match_user_id, match_native, match_learning) in enumerate(self.pending_matches):
            if (match_native == learning_language and match_learning == native_language and
                    match_user_id != user_id):
                # Match found
                session = LanguageExchangeSession(
                    session_id=f"sess_{len(self.sessions)+1}",
                    user1_id=user_id,
                    user2_id=match_user_id,
                    language1=native_language,
                    language2=learning_language
                )
                self.sessions[session.session_id] = session
                self.pending_matches.pop(i)
                return session

        # No match — add to pending
        self.pending_matches.append((user_id, native_language, learning_language))
        return None

    def get_session(self, session_id):
        return self.sessions.get(session_id)

    def send_message(self, session_id, sender_id, text, auto_translate=True):
        session = self.sessions.get(session_id)
        if not session or session.status != "active":
            raise ValueError("Invalid or inactive session")

